 path=J/'agent_b/collect_capacity_metrics.py';assert sha(path)=='f117a1a0e615881b079016b25ae28ca76d605a14e5b54d59af832b7bdcfdec9d';s=importlib.util.spec_from_file_location('frozen_capacity_reporting',path);m=importlib.util.module_from_spec(s);s.loader.exec_module(m)
